"params": {"phrase_slack": 3, "guard_outcome": {"self_harm": "self_harm"}, "guard_message_key": {"self_harm": "guard_self_harm"}, "guard_category_order": ["self_harm", "hate", "sexual", "violence", "profanity"], "guard_block_min_severity": {"hate": 1, "sexual": 1, "violence": 1, "profanity": 1, "self_harm": 1}}, "enabled": true}, {"note": "Exact curated Q match. Whole QA block runs before any document retrieval.", "step": "qa_exact", "on_hit": "stop", "params": {"form": ["norm", "lemma", "stem"]}, "enabled": true}, {"step": "qa_lexical", "on_hit": "stop", "params": {"form": ["norm", "lemma", "stem"], "fetch_k": 50, "synonyms": true, "suggest_top_n": 3, "trgm_suggest_min": 0.40, "other_grade_top_n": 2, "other_grade_min_ratio": 0.5}, "enabled": true}, {"note": "Document chunks by fulltext on ts_lemma||ts_stem (reduced forms).", "step": "document_lexical", "on_hit": "continue", "params": {"form": ["lemma", "stem"], "fetch_k": 30, "body_weight": "B", "bm25_lexical": true, "heading_pass": true, "idf_coverage": true, "max_concepts": 8, "min_coverage": 0.5, "trgm_fetch_k": 15, "trgm_min_sim": 0.35, "trgm_fallback": true, "bm25_min_ratio": 0.65, "heading_weight": "A", "bm25_max_df_share": 0.25, "rank_tiebreak_cap": 0.999, "topical_admission": true, "heading_max_df_share": 0.25, "heading_numeric_pass": false, "rank_tiebreak_weight": 0.001, "trgm_min_typo_coverage": 0.5}, "enabled": true}, {"note": "Fallback: match query tokens against edu_ai_chunk_keywords.keywords[] (reduced same way). Runs only if rag_lexical was empty.", "step": "rag_keywords", "on_hit": "continue", "params": {"form": ["lemma", "stem"], "fetch_k": 30, "min_overlap": 2, "heading_quality": 1.0, "topical_admission": true, "topical_max_df_share": 0.25}, "enabled": false, "only_if_empty": false}, {"note": "Curated QA vector. Ends the QA block; documents only if QA found nothing.", "step": "qa_vector", "on_hit": "stop", "params": {"cosine_min": 0.65}, "enabled": true}, {"note": "Last resort: semantic neighbours over document_chunks.embedding. cosine_min drops off-topic so the pool stays empty -> no_answer.", "step": "rag_vector", "on_hit": "continue", "params": {"top_k": 5, "fetch_k": 30, "cosine_min": 0.45, "heading_quality": 1.0, "grade_query_enrich": true, "grade_query_prefix": "Pro {grade}. ročník: "}, "enabled": true, "only_if_empty": false, "run_on_timespan": true, "only_if_max_coverage_below": 0.75}, {"note": "Completes a matched section with its remaining chunks (same file_item_uuid). Context, not evidence: siblings get no score or coverage. max_chunks_per_element is a BUDGET per element including the matched chunks — under it the whole section comes in, over it chunks are taken outwards from the match until it is spent. window is an optional hard cap on that distance; 0 = budget only.", "step": "document_siblings", "on_hit": "continue", "params": {"window": 0, "grade_recall": "from_pool_docs", "grade_recall_max": 8, "max_chunks_per_element": 6}, "enabled": false}, {"note": "Single terminal LLM. Empty pool -> no_answer (no LLM call).", "step": "answer", "params": {"model": "gpt-5.6-luna", "rrf_k": 1, "focus_gate": true, "max_tokens": 2000, "bm25_weight": 0.03, "grade_scope": "focus_if_match", "rerank_mode": "cloud", "temperature": 0, "domain_match": true, "focus_max_df": 0.05, "llm_variants": {"enabled": true, "max_tokens": 200, "temperature": 0, "reasoning_effort": "medium"}, "rerank_model": "gpt-5.6-luna", "rerank_top_k": 20, "token_budget": 8000, "content_top_n": 5, "focus_require": "all", "priority_tier": true, "rerank_output": "graded", "sources_top_n": 3, "keyword_weight": 1.0, "rerank_reorder": true, "thin_max_chars": 120, "attrib_best_min": 0.25, "chars_per_token": 4, "include_excerpt": true, "rerank_min_keep": 6, "seed_scan_depth": 15, "thin_guard_seed": true, "binding_fallback": true, "log_candidates_n": 20, "reasoning_effort": "medium", "rerank_prefilter": {"model": "jina-reranker-v3", "top_n": 20, "max_in": 40, "backend": "jina", "timeout_s": 10, "keep_anchor": true, "passage_chars": 400}, "rerank_score_min": 0, "rerank_timeout_s": 15, "source_min_ratio": 0.5, "thin_guard_judge": true, "excerpt_cut_ratio": 0.6, "excerpt_max_chars": 4000, "rerank_seed_top_n": 12, "priority_min_ratio": 0.65, "thin_require_digit": false, "heading_match_boost": 0.12, "rerank_log_passages": false, "source_ratio_anchor": "tier_first", "rerank_passage_chars": 500, "rerank_require_grade": 2, "attrib_positional_min": 0.15, "grade_chunk_min_ratio": 0.8, "rerank_grade_ordering": false, "vector_element_weight": 1.0, "domain_kw_max_df_share": 0.25, "clarify_max_match_score": 1.0, "max_chunks_per_document": 6, "rerank_reasoning_effort": "low", "related_suggestions_top_n": 3}, "enabled": true}], "visibility": {"note": "child_may_publish_organization is enforced at ingest (/ingest-principal): true lets a unit choose organization, which reaches its parent and sibling units — never another legal person. entity_visible_to_parent is enforced at query time (scope.where). Both tighten when false.", "search_requires_user": false, "entity_visible_to_parent": true, "child_may_publish_organization": true}, "tokenization": {"active": true}, "normalization": {"lowercase": true, "drop_stopwords": true, "strip_diacritics": true}}', 'Org copy of the global v3 config (settings belong to one top-level organisation, init 98). Full copy, not a diff.', '2026-08-04 14:07:02.252597+00', 'ZAKLADNI_SKOLA_BOROVA');
